    fetchText('ip-ownership-register.json'),fetchText('software-supply-chain-summary.json'),fetchText('portfolio-audit-certificate.json'),fetchText('rights-transfer-register.json'),fetchText('project-presentations.json'),fetchText('project-evaluations.json'),fetchText('acquisition-contribution-policy.json'),fetchText('project-connections.json')
